"""Famous road trips for the Virtual Tour. See build_virtual_tour.py.

T(id, name, countries, start, end, via, km, duration, best_time, kind, summary, highlights, tip)
  countries   ISO codes, space separated
  via         optional waypoints for the map link, separated by ';'
  km          approximate length (as commonly quoted)
  end == start marks a loop
Distances are approximate; always check current road conditions and closures.
"""


def T(id, name, countries, start, end, via, km, duration, best_time, kind, summary, highlights, tip):
    return {
        "id": id, "name": name, "countries": countries.split(), "start": start, "end": end,
        "via": [v.strip() for v in via.split(";") if v.strip()], "km": km, "duration": duration,
        "best_time": best_time, "kind": kind, "summary": summary,
        "highlights": [h.strip() for h in highlights.split(";") if h.strip()], "tip": tip,
    }


